40	        <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Telefone</label>
41	        <input value={telefone} onChange={(e) => setTelefone(e.target.value)}
42	          className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
