58	const GarcomCard = ({ garcom, onMudou }) => {
59	  const [copiado, setCopiado] = useState(false);
60	  const [modo, setModo] = useState('online'); // 'online' | 'local'
61	  const urls = getLocalUrls(`/garcom/${garcom.login_key}`);
62	  const link = modo === 'local' && urls.lan ? urls.lan : urls.principal;
63	
64	  const copiarLink = () => {
65	    navigator.clipboard?.writeText(link);
66	    setCopiado(true);
67	    setTimeout(() => setCopiado(false), 2000);
68	  };
69	
70	  const togglePermissao = async (chave) => {
71	    // pagamento_parcial é default ligado (undefined = true) — as outras são default desligado.
72	    const atual = chave === 'pagamento_parcial' ? garcom.permissoes?.[chave] !== false : !!garcom.permissoes?.[chave];
73	    await atualizarGarcom(garcom.id, { permissoes: { ...garcom.permissoes, [chave]: !atual } });
74	    onMudou();
75	  };
76	
77	  const toggleAtivo = async () => {
78	    await atualizarGarcom(garcom.id, { ativo: !garcom.ativo });
79	    onMudou();
