107	              Logado em 1 dispositivo
108	            </span>
109	          )}
110	        </div>
111	      </div>
112	
113	      {urls.lan && (
114	        <div className="flex gap-2 mt-3">
115	          <button onClick={() => setModo('online')}
116	            className={`px-3 py-1 rounded-lg text-[10px] font-bold ${modo === 'online' ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'}`}>
117	            ONLINE
118	          </button>
119	          <button onClick={() => setModo('local')}
120	            className={`px-3 py-1 rounded-lg text-[10px] font-bold ${modo === 'local' ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'}`}>
121	            LOCAL
122	          </button>
