125	      <div className="flex items-center gap-2 mt-2 bg-[#F4F4F5] dark:bg-[#3F3F46] rounded-xl px-3 py-2">
126	        <span className="text-xs font-mono text-[#71717A] dark:text-[#A1A1AA] truncate flex-1">{link}</span>
127	        <button onClick={copiarLink} className="text-xs font-bold text-[#FF441F]">{copiado ? 'Copiado!' : 'Copiar'}</button>
128	      </div>
129	
130	      <div className="flex flex-wrap gap-2 mt-3">
131	        {/* Default ligado (diferente de futuras permissões) — pagamento parcial já era
132	            permitido sem restrição antes dessa permissão existir, então só desativa quem
133	            o dono desmarcar. Toggles de desconto/cancelar/acréscimo foram removidos daqui
134	            porque o garçom nunca teve essas ações na tela dele — eram vestigiais. */}
135	        <button onClick={() => togglePermissao('pagamento_parcial')}
136	          className={`text-[10px] px-2 py-1 rounded-full font-medium border ${
137	            garcom.permissoes?.pagamento_parcial !== false ? 'bg-blue-50 dark:bg-blue-950/40 text-blue-700 dark:text-blue-400 border-blue-200 dark:border-blue-800' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#A1A1AA] border-[#E4E4E7] dark:border-[#3F3F46]'
