139	          Pagamento parcial
140	        </button>
141	      </div>
142	
143	      {garcom.sessao_ativa && (
144	        <button onClick={forcarLogout} className="w-full mt-3 py-1.5 text-xs border border-amber-300 dark:border-amber-800 text-amber-700 dark:text-amber-400 rounded-lg hover:bg-amber-50 dark:hover:bg-amber-950/40 font-medium">
145	          Forçar logout (liberar outro dispositivo)
