1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { getFilaChamadaBalcao, marcarChamadaBalcao, marcarItemBalcaoEntregue } from '../../services/restauranteService';
3	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
4	import { useNowTick } from '../../hooks/useNowTick';
5	import Icon from '../../components/AppIcon';
6	
7	const CICLO_MS = 7000;
8	const MAX_CHAMADOS = 5;
9	
10	// Painel de chamada da Venda Balcão — fica ligado numa TV/tablet no salão. Chama 1
11	// comanda por vez (a mais antiga ainda com chamado_count < 5), bipa+pisca a cada 7s.
12	// Depois de 5 chamados sem confirmação, sai do destaque e cai na lista lateral
13	// "Aguardando entregar" (silenciosa) até o operador marcar os itens como entregues.
14	// Item pode ser marcado entregue a qualquer momento (ex: bebida que o cliente já
15	// levou na hora), sem precisar esperar o resto do pedido — a comanda só some da
16	// fila quando TODOS os itens dela estiverem entregues.
17	const RestauranteChamada = () => {
18	  const [fila, setFila] = useState([]);
19	  const [historico, setHistorico] = useState([]);
20	  const [erro, setErro] = useState(null);
21	  const [flash, setFlash] = useState(false);
22	  const now = useNowTick();
23	  const tocarSom = useNotificacaoSonora('chamada');
24	  const chamandoRef = useRef(false);
25	  const filaRef = useRef([]);
26	
27	  const carregar = useCallback(async () => {
28	    try {
29	      const { fila: nova } = await getFilaChamadaBalcao();
30	      const idsNovos = new Set(nova.map((p) => p.order_id));
31	      const anterior = filaRef.current;
32	      const saidosInfo = anterior.filter((p) => !idsNovos.has(p.order_id));
33	      if (saidosInfo.length && anterior.length) {
34	        setHistorico((h) => [...saidosInfo.map((p) => ({ ...p, entregue_em: Date.now() })), ...h].slice(0, 15));
35	      }
36	      filaRef.current = nova;
37	      setFila(nova);
38	      setErro(null);
39	    } catch (err) {
40	      setErro(err.message);
41	    }
42	  }, []);
43	
44	  useEffect(() => {
45	    carregar();
46	    const id = setInterval(carregar, 5000);
47	    return () => clearInterval(id);
48	  }, [carregar]);
49	
50	  const filaVisivel = fila.filter((p) => p.itens.length > 0);
51	  const central = filaVisivel.find((p) => p.chamado_count < MAX_CHAMADOS) ?? null;
52	  const aguardando = filaVisivel.filter((p) => p.chamado_count >= MAX_CHAMADOS);
53	  const naFila = filaVisivel.filter((p) => p.chamado_count < MAX_CHAMADOS && p.order_id !== central?.order_id).length;
54	
55	  // Ciclo de 7s: dispara bipe+pisca e registra a chamada no servidor (sobrevive a
56	  // reload da TV, já que o contador/última chamada ficam persistidos na comanda).
57	  useEffect(() => {
58	    if (!central || chamandoRef.current) return;
59	    const ultima = central.ultima_chamada_em ? new Date(central.ultima_chamada_em).getTime() : null;
60	    const devido = ultima === null || now - ultima >= CICLO_MS;
61	    if (!devido) return;
62	
63	    chamandoRef.current = true;
64	    tocarSom();
65	    setFlash(true);
66	    setTimeout(() => setFlash(false), 700);
67	
68	    marcarChamadaBalcao(central.order_id)
69	      .then(() => {
70	        const atualizada = filaRef.current.map((p) => p.order_id === central.order_id
71	          ? { ...p, chamado_count: p.chamado_count + 1, ultima_chamada_em: new Date().toISOString() }
72	          : p);
73	        filaRef.current = atualizada;
74	        setFila(atualizada);
75	      })
76	      .catch(() => {})
77	      .finally(() => { chamandoRef.current = false; });
78	    // eslint-disable-next-line react-hooks/exhaustive-deps
79	  }, [now, central?.order_id, central?.ultima_chamada_em]);
80	
81	  const marcarEntregue = async (orderId, itemId) => {
82	    try {
83	      await marcarItemBalcaoEntregue(orderId, itemId);
84	      const atualizada = filaRef.current.map((p) => p.order_id !== orderId ? p : { ...p, itens: p.itens.filter((i) => i.id !== itemId) });
85	      filaRef.current = atualizada;
86	      setFila(atualizada);
87	    } catch (err) {
88	      setErro(err.message);
89	    }
90	  };
91	
92	  const ItensLista = ({ pedido, tamanho = 'sm' }) => (
93	    <div className="space-y-1.5">
94	      {pedido.itens.map((item) => (
95	        <div key={item.id} className={`flex items-center justify-between gap-2 bg-black/20 rounded-lg px-2.5 py-1.5 ${tamanho === 'lg' ? 'text-base' : 'text-xs'}`}>
96	          <span className="font-bold text-white">{item.quantity}x {item.product_name}</span>
97	          <button onClick={() => marcarEntregue(pedido.order_id, item.id)}
98	            className="flex-shrink-0 px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-bold rounded-lg flex items-center gap-1">
99	            <Icon name="Check" size={11} /> Entregue
100	          </button>
101	        </div>
102	      ))}
103	    </div>
104	  );
105	
106	  return (
107	    <div className="min-h-screen bg-[#1A1A1A] p-4 sm:p-6 flex flex-col">
108	      <div className="flex items-center justify-between mb-4">
109	        <h1 className="text-xl font-black text-white uppercase flex items-center gap-2">
110	          <Icon name="Volume2" size={22} className="text-orange-400" /> Chamada — Balcão
111	        </h1>
112	        <div className="flex items-center gap-3">
113	          {naFila > 0 && <span className="text-xs font-bold text-[#71717A] dark:text-[#A1A1AA]">+{naFila} na fila</span>}
114	          <button onClick={carregar} title="Atualizar dados" className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
115	            <Icon name="RefreshCw" size={16} />
116	          </button>
117	        </div>
118	      </div>
119	      {erro && <p className="text-sm text-red-400 mb-3">{erro}</p>}
120	
121	      <div className="flex-1 flex flex-col lg:flex-row gap-6">
122	        {/* Destaque central — 1 comanda por vez, pisca contínuo + flash no bipe */}
123	        <div className="flex-1 flex items-center justify-center">
124	          {central ? (
125	            <div className={`w-full max-w-xl rounded-3xl border-4 p-8 text-center transition-colors animate-pulse ${flash ? 'bg-yellow-400/20 border-yellow-400 dark:border-yellow-800' : 'bg-[#232323] border-orange-500/60'}`}>
126	              <p className="text-sm font-bold text-orange-400 uppercase tracking-widest mb-2">Pedido pronto</p>
127	              <p className="text-4xl font-black text-white mb-1">{central.cliente}</p>
128	              <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mb-5">Chamado {central.chamado_count}/{MAX_CHAMADOS}</p>
129	              <ItensLista pedido={central} tamanho="lg" />
130	            </div>
131	          ) : (
132	            <p className="text-[#71717A] dark:text-[#A1A1AA] text-sm">Nenhum pedido de balcão aguardando.</p>
133	          )}
134	        </div>
135	
136	        {/* Lateral — Aguardando entregar (silencioso) + Entregue (histórico) */}
137	        <div className="w-full lg:w-80 flex-shrink-0 flex flex-col gap-4 max-h-[80vh]">
138	          <div className="flex-1 overflow-y-auto">
