1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getSalaoComandaDetalhe, getMeusProdutos, getMeusCombos, abrirVendaBalcao,
5	  adicionarItensComandaSalao, editarItemComandaSalao, removerItemComandaSalao,
6	  aplicarDescontoComanda, aplicarAcrescimoComanda, cancelarComandaSalao, pagarComandaSalao,
7	  registrarPagamentoParcialSalao, alterarTrocoPixComandaSalao, removerPagamentoParcialSalao,
8	  editarClienteComandaSalao, getConfig,
9	} from '../../services/restauranteService';
10	import Icon from '../../components/AppIcon';
11	import { printReciboCliente } from '../../utils/printComanda';
12	import { agruparItensComanda, quantidadeGrupoCombo } from '../../utils/agruparItensComanda';
13	import QuickAddProdutoModal from '../../components/restaurante/QuickAddProdutoModal';
14	
15	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
16	const PAGAMENTO_LABEL = { pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito', cash: 'Dinheiro' };
17	
18	// Venda balcão — comanda avulsa (sem mesa/cliente) com layout tipo PDV de mercado:
19	// catálogo de produtos de um lado, carrinho + pagamento do outro. Reaproveita os
20	// mesmos endpoints de comanda (itens, desconto/acréscimo, pagamento parcial,
21	// pagar) — o cliente pode dividir o pagamento em pix + dinheiro + cartão na mesma
22	// venda, cada parcela com sua própria taxa de cartão quando for o caso.
23	// Antes vivia como botão+modal dentro de /restaurante/salao — agora é rota própria
24	// no menu lateral (fora do módulo Salão), pedido do usuário.
25	const RestauranteVendaBalcao = () => {
26	  const navigate = useNavigate();
27	  const [comandaId, setComandaId] = useState(null);
28	  const [erroAbertura, setErroAbertura] = useState(null);
29	  const [comanda, setComanda] = useState(null);
30	  const [produtos, setProdutos] = useState([]);
31	  const [busca, setBusca] = useState('');
32	  const [categoria, setCategoria] = useState('todas');
33	  const [produtoAtivo, setProdutoAtivo] = useState(null);
34	
35	  const [descontoInput, setDescontoInput] = useState('');
36	  const [acrescimoInput, setAcrescimoInput] = useState('');
37	  const [taxaCartaoPercentual, setTaxaCartaoPercentual] = useState(0);
38	  const [nomeCliente, setNomeCliente] = useState('');
39	
40	  const [valorPagamento, setValorPagamento] = useState('');
41	  const [formaPagamentoParcial, setFormaPagamentoParcial] = useState('pix');
42	  const [valorRecebidoParcial, setValorRecebidoParcial] = useState('');
43	  const [trocoViaPixParcial, setTrocoViaPixParcial] = useState(false);
44	
45	  const [forma, setForma] = useState('pix');
46	  const [valorRecebidoFinal, setValorRecebidoFinal] = useState('');
47	  const emAndamentoRef = useRef(false);
48	
49	  const [erro, setErro] = useState(null);
50	  const [salvando, setSalvando] = useState(false);
51	
52	  // Venda balcão não pode virar comanda "fantasma" aberta pra sempre se o operador
53	  // sair sem finalizar — finalizadaRef marca quando a comanda já chegou num estado
54	  // terminal tratado explicitamente (paga ou cancelada). comandaIdRef existe porque
55	  // o cleanup do efeito de desmontagem roda numa closure antiga e precisa do valor
56	  // mais recente do id (setado de forma assíncrona depois que a página abre).
57	  const finalizadaRef = useRef(false);
58	  const comandaIdRef = useRef(null);
59	
60	  // Cada visita a essa página abre uma venda balcão nova — mesmo comportamento do
61	  // botão que existia antes dentro de Salão.
62	  useEffect(() => {
63	    abrirVendaBalcao().then((c) => setComandaId(c.id)).catch((err) => setErroAbertura(err.message));
64	  }, []);
65	
66	  useEffect(() => { comandaIdRef.current = comandaId; }, [comandaId]);
67	
68	  // Rede de segurança pra saídas que não passam pelos botões (ex: voltar do
69	  // navegador) — cancela a comanda ainda aberta ao desmontar, sem isso ela nunca
70	  // mais aparece nessa tela mas continua "aberta" pro resto do sistema. Sem await:
71	  // o componente já está indo embora, se falhar não tem UI pra mostrar o erro.
72	  useEffect(() => {
73	    return () => {
74	      if (comandaIdRef.current && !finalizadaRef.current) {
75	        cancelarComandaSalao(comandaIdRef.current).catch(() => {});
76	      }
77	    };
78	  }, []);
79	
80	  const carregar = useCallback(async () => {
81	    if (!comandaId) return;
82	    const [c, produtosResp, combosResp] = await Promise.all([
83	      getSalaoComandaDetalhe(comandaId),
84	      getMeusProdutos(),
85	      getMeusCombos(),
86	    ]);
87	    setComanda(c);
88	    setDescontoInput(String(c.desconto_valor ?? 0));
89	    setAcrescimoInput(String(c.acrescimo_valor ?? 0));
90	    setNomeCliente((atual) => (atual ? atual : (c.cliente_mesa_nome === 'Venda balcão' ? '' : (c.cliente_mesa_nome ?? ''))));
91	    // Refaz a lista de produtos toda vez que a comanda recarrega — senão a quantidade
92	    // em estoque mostrada no picker fica desatualizada depois de incluir/editar item.
93	    setProdutos([
94	      ...(produtosResp.produtos ?? []),
95	      ...(combosResp.combos ?? []).filter((c2) => c2.disponivel).map((c2) => ({ ...c2, tipo: 'combo', category_name: 'Combos' })),
96	    ]);
97	  }, [comandaId]);
98	
99	  useEffect(() => { carregar(); }, [carregar]);
100	  useEffect(() => {
101	    getConfig().then((c) => setTaxaCartaoPercentual(c.taxa_cartao_percentual ?? 0)).catch(() => {});
102	  }, []);
103	
104	  const isCartao = (f) => f === 'credit_card' || f === 'debit_card';
105	
106	  const acao = async (fn) => {
107	    // Guard síncrono (ref, não state) — clique duplo muito rápido pode disparar 2x
108	    // antes do `disabled={salvando}` re-renderizar, duplicando lançamento financeiro
109	    // (foi o caso real: 2 entradas de dinheiro idênticas pra mesma comanda).
110	    if (emAndamentoRef.current) return;
111	    emAndamentoRef.current = true;
112	    setErro(null);
113	    setSalvando(true);
114	    try {
115	      await fn();
116	      await carregar();
117	    } catch (err) {
118	      setErro(err.message);
119	    } finally {
120	      emAndamentoRef.current = false;
121	      setSalvando(false);
122	    }
123	  };
124	
125	  const adicionar = (item) => acao(() => adicionarItensComandaSalao(comandaId, [item]));
126	
127	  const alterarQuantidade = (item, delta) => {
128	    const novaQtd = item.quantity + delta;
129	    if (novaQtd < 1) {
130	      acao(() => removerItemComandaSalao(comandaId, item.id));
131	      return;
132	    }
133	    acao(() => editarItemComandaSalao(comandaId, item.id, { quantity: novaQtd }));
134	  };
135	
136	  const removerItem = (item) => acao(() => removerItemComandaSalao(comandaId, item.id));
137	
138	  const aplicarDesconto = () => acao(() => aplicarDescontoComanda(comandaId, Number(descontoInput || 0)));
139	  const aplicarAcrescimo = () => acao(() => aplicarAcrescimoComanda(comandaId, Number(acrescimoInput || 0)));
140	
141	  const salvarNomeCliente = () => acao(() => editarClienteComandaSalao(comandaId, nomeCliente.trim() || 'Venda balcão'));
142	
143	  const registrarPagamento = () => {
