464	                    <span className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Troco via Pix (não sai do caixa em espécie)</span>
465	                  </label>
466	                )}
467	              </div>
468	            )}
469	            <button onClick={registrarPagamento} disabled={!valorPagamento || salvando}
470	              className="w-full px-2.5 py-1.5 bg-zinc-800 text-white rounded-lg text-xs font-bold disabled:opacity-40">
471	              Adicionar pagamento
472	            </button>
473	          </div>
474	
475	          {erro && <p className="text-xs text-red-600 dark:text-red-400 mt-2">{erro}</p>}
476	
477	          {saldo > 0.01 && (
478	            <p className="text-xs text-amber-700 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 rounded-xl px-3 py-2 mt-2">
479	              Ainda falta {fmt(saldo)} de saldo devedor. Adicione os pagamentos acima (com a forma de cada um) até zerar pra poder finalizar.
480	            </p>
481	          )}
482	
483	          <div className="flex gap-2 mt-4">
484	            <button onClick={cancelar} disabled={salvando}
485	              className="flex-1 py-2.5 text-sm font-bold rounded-xl border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 disabled:opacity-50">
486	              Cancelar venda
487	            </button>
488	            <button onClick={finalizar} disabled={salvando || (comanda.itens ?? []).length === 0 || saldo > 0.01}
489	              title={saldo > 0.01 ? 'Registre os pagamentos até o saldo zerar' : undefined}
490	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
491	              {salvando ? 'Processando...' : 'Finalizar venda'}
492	            </button>
493	          </div>
494	        </div>
495	      </div>
496	
497	      {produtoAtivo && (
498	        <QuickAddProdutoModal
499	          produto={produtoAtivo}
500	          onFechar={() => setProdutoAtivo(null)}
501	          onConfirmar={async (item) => { await adicionar(item); setProdutoAtivo(null); }}
502	        />
503	      )}
504	    </div>
505	  );
