31	
32	// Estabelecimento abre mesa/comanda direto, sem precisar de garçom.
33	const AbrirComandaModal = ({ mesa, onFechar, onAberta }) => {
34	  const [nome, setNome] = useState('');
35	  const [telefone, setTelefone] = useState('');
36	  const [erro, setErro] = useState(null);
37	  const [salvando, setSalvando] = useState(false);
38	
39	  const submit = async (e) => {
40	    e.preventDefault();
41	    setErro(null);
42	    setSalvando(true);
43	    try {
44	      const comanda = await abrirComandaSalao({ mesa_id: mesa?.id ?? null, cliente_nome: nome.trim(), cliente_telefone: telefone.trim() });
45	      onAberta(comanda);
46	    } catch (err) {
47	      setErro(err.message ?? 'Não foi possível abrir a comanda.');
48	    } finally {
49	      setSalvando(false);
50	    }
51	  };
52	
53	  return (
54	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
55	      <div className="bg-white dark:bg-[#27272A] rounded-2xl p-6 w-full max-w-sm shadow-2xl">
56	        <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5] mb-1">
57	          {mesa ? `Abrir Mesa ${mesa.numero}` : 'Abrir comanda avulsa'}
58	        </h2>
59	        <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mb-4">Nome e telefone do cliente são obrigatórios antes de vender.</p>
60	        <form onSubmit={submit} className="space-y-3">
61	          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do cliente" required
62	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
63	          <input value={telefone} onChange={(e) => setTelefone(e.target.value)} placeholder="Telefone do cliente" required
64	            className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
65	          {erro && <p className="text-xs text-red-600 dark:text-red-400">{erro}</p>}
66	          <div className="flex gap-2 pt-1">
67	            <button type="button" onClick={onFechar}
68	              className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">
69	              Cancelar
70	            </button>
71	            <button type="submit" disabled={salvando}
72	              className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
73	              {salvando ? 'Abrindo...' : 'Abrir'}
74	            </button>
75	          </div>
76	        </form>
77	      </div>
78	    </div>
79	  );
80	};
81	
82	// Picker de produto com busca + filtro por categoria — mesmo padrão do garçom
83	// (garcom-portal), reaproveitado aqui pro estabelecimento incluir item na comanda.
84	const ProdutoPickerModal = ({ produtos, onFechar, onAdicionado }) => {
85	  const [busca, setBusca] = useState('');
86	  const [categoria, setCategoria] = useState('todas');
87	  const [produtoAtivo, setProdutoAtivo] = useState(null);
88	
89	  // meusProdutos() traz tudo (até inativo/sem estoque) pra alimentar a tela de admin —
90	  // aqui é picker de venda, filtra estoque zerado/nulo antes de oferecer pro dono.
91	  // Combo não tem quantidade_estoque (não é o mesmo controle dos produtos avulsos) —
92	  // o filtro de estoque zerado só vale pra produto normal.
93	  const vendaveis = produtos.filter((p) => p.tipo === 'combo' || (p.quantidade_estoque ?? 0) > 0);
94	  const categorias = ['todas', ...new Set(vendaveis.map((p) => p.category_name ?? 'Outros'))];
95	  const filtrados = vendaveis.filter((p) => {
96	    const bateBusca = p.name.toLowerCase().includes(busca.toLowerCase());
97	    const bateCategoria = categoria === 'todas' || (p.category_name ?? 'Outros') === categoria;
98	    return bateBusca && bateCategoria;
99	  });
100	
101	  return (
102	    <div className="fixed inset-0 bg-white dark:bg-[#27272A] z-[55] flex flex-col">
103	      <div className="p-4 border-b border-[#E4E4E7] dark:border-[#3F3F46] sticky top-0 bg-white dark:bg-[#27272A] max-w-2xl w-full mx-auto">
104	        <div className="flex items-center gap-2 mb-3">
105	          <button onClick={onFechar} className="p-1 text-[#71717A] dark:text-[#A1A1AA]"><Icon name="ArrowLeft" size={20} /></button>
106	          <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">Adicionar produto</h2>
107	        </div>
108	        <div className="flex items-center gap-2">
109	          <div className="relative flex-1">
110	            <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" />
111	            <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto..." autoFocus
112	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
113	          </div>
114	          {categorias.includes('Combos') && (
115	            <button type="button" onClick={() => setCategoria((c) => (c === 'Combos' ? 'todas' : 'Combos'))}
116	              className={`flex items-center gap-1 px-3 py-2.5 rounded-xl text-sm font-bold whitespace-nowrap flex-shrink-0 ${
117	                categoria === 'Combos' ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#18181B] dark:text-[#F4F4F5]'
118	              }`}>
119	              <Icon name="Package" size={15} /> Combos
120	            </button>
121	          )}
122	        </div>
123	        <div className="flex gap-1.5 mt-3 overflow-x-auto pb-1">
124	          {categorias.map((c) => (
125	            <button key={c} onClick={() => setCategoria(c)}
126	              className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap flex-shrink-0 ${
127	                categoria === c ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] dark:bg-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'
128	              }`}>
129	              {c === 'todas' ? 'Todas' : c}
130	            </button>
131	          ))}
132	        </div>
133	      </div>
134	
135	      <div className="flex-1 overflow-y-auto p-4 max-w-2xl w-full mx-auto space-y-2">
136	        {filtrados.map((p) => (
137	          <button key={`${p.tipo ?? 'produto'}-${p.id}`} onClick={() => setProdutoAtivo(p)}
138	            className="w-full bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl p-2.5 flex items-center gap-3 text-left active:scale-[0.98] transition-transform">
139	            <div className="w-12 h-12 rounded-lg overflow-hidden bg-[#F4F4F5] dark:bg-[#3F3F46] flex-shrink-0">
140	              {p.image_url
141	                ? <img src={p.image_url} alt="" className="w-full h-full object-cover" />
142	                : <div className="w-full h-full flex items-center justify-center"><Icon name={p.tipo === 'combo' ? 'Package' : 'UtensilsCrossed'} size={18} className="text-[#A1A1AA]" /></div>}
143	            </div>
144	            <div className="min-w-0 flex-1">
145	              <p className="text-sm font-semibold text-[#18181B] dark:text-[#F4F4F5] truncate">
146	                {p.tipo === 'combo' && <span className="text-[10px] font-bold text-[#FF441F] mr-1">COMBO</span>}
147	                {p.name}
148	              </p>
149	              <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">
150	                {p.preco_promo != null && <span className="line-through text-[#A1A1AA] mr-1">{fmt(p.price)}</span>}
151	                {fmt(p.preco_promo ?? p.price)}
152	                {p.quantidade_estoque != null && <span className="text-[#A1A1AA]"> · estoque: {p.quantidade_estoque}</span>}
153	              </p>
154	            </div>
155	            <Icon name="Plus" size={18} className="text-[#FF441F] flex-shrink-0" />
156	          </button>
157	        ))}
158	        {filtrados.length === 0 && <p className="text-sm text-[#A1A1AA] text-center py-6">Nenhum produto encontrado.</p>}
159	      </div>
160	
161	      {produtoAtivo && (
162	        <QuickAddProdutoModal
163	          produto={produtoAtivo}
164	          onFechar={() => setProdutoAtivo(null)}
165	          onConfirmar={async (item) => { await onAdicionado(item); setProdutoAtivo(null); }}
