      "amount": { "value": 29800 },
      "text": "00020126360014BR.GOV.BCB.PIX...",
      "links": [
        { "rel": "QRCODE.PNG", "href": "https://sandbox.api.assets.pagseguro.com/qrcode/....png" }
      ]
    }
