}

===============================================================================
3) CRIAR PEDIDO — PAGAMENTO VIA CARTÃO (crédito/débito)
===============================================================================
POST /orders
Authorization: Bearer {token_sandbox}
Content-Type: application/json
x-api-version: 4.0

Request:
{
  "reference_id": "PED_1043",
  "customer": {
    "name": "Cliente Teste",
    "email": "cliente.teste@exemplo.com",
    "tax_id": "12345678909"
  },
  "items": [
    { "name": "Combo Dourada Família", "quantity": 1, "unit_amount": 29800 }
  ],
  "notification_urls": [
    "https://deliveryhub.teusite.top/api/pagamentos/webhook"
  ],
  "charges": [
    {
      "reference_id": "CHG_PED_1043",
      "description": "Pedido delivery",
      "amount": { "value": 29800, "currency": "BRL" },
      "payment_method": {
        "type": "CREDIT_CARD",
        "installments": 1,
        "capture": true,
        "card": { "encrypted": "006E7RVEmvXHU7pHYYCLh0BRnU6...(token gerado pelo PagBank.js)" },
        "holder": { "name": "Cliente Teste", "tax_id": "12345678909" }
      }
    }
  ]
}

Response 201:
{
  "id": "ORDE_YYYYYYYYYYYYYYYY",
  "reference_id": "PED_1043",
  "charges": [
    {
      "id": "CHAR_YYYYYYYYYYYYYYYY",
      "reference_id": "CHG_PED_1043",
      "status": "PAID",
      "amount": { "value": 29800, "currency": "BRL" },
      "payment_response": { "code": "20000", "message": "SUCCESS" },
      "payment_method": {
        "type": "CREDIT_CARD",
        "installments": 1,
        "card": { "brand": "VISA", "first_digits": "401200", "last_digits": "1112" }
      }
    }
  ]
}

